import java.io.*;
import java.util.*;

public class Solution {
    static class Reader {
        BufferedReader br;
        StringTokenizer st;

        Reader() {
            br = new BufferedReader(new InputStreamReader(System.in));
            st = null;
        }

        String readToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    System.out.println(e);
                }
            }
            return st.nextToken();
        }

        int readInt() {
            return Integer.parseInt(readToken());
        }

        long readLong() {
            return Long.parseLong(readToken());
        }

        double readDouble() {
            return Double.parseDouble(readToken());
        }

        String readLine() {
            try {
                if (st == null || !st.hasMoreTokens()) {
                    st = new StringTokenizer(br.readLine());
                }
            } catch (IOException e) {
                System.out.println(e);
            }
            return st.nextToken("\n");
        }
    }

    static final long MOD = 998244353L;
    static final int MAXN = 200005;
    static long[] factArr = new long[MAXN];

    static long modPow(long base, long exp, long mod) {
        long res = 1L;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    static long nCr(int n, int r) {
        if (r > n) return 0L;
        return factArr[n] * modPow(factArr[r], MOD - 2, MOD) % MOD * modPow(factArr[n - r], MOD - 2, MOD) % MOD;
    }

    static long computeSum(int n, int k) {
        long total = 0;
        for (int i = 0; i <= n - k; i++) {
            long val = nCr(n - k, i) * modPow(n - k - i, n, MOD) % MOD;
            if (i % 2 == 0) total = (total + val) % MOD;
            else total = (total - val + MOD) % MOD;
        }
        return total;
    }

    public static void main(String[] args) {
        Reader r = new Reader();
        int t = 1;
        // t = r.readInt();
        for (int q = 0; q < t; q++) {
            long n = r.readLong();
            long k = r.readLong();
            factArr[0] = 1;
            for (long i = 1; i <= n; i++) {
                factArr[(int) i] = factArr[(int) (i - 1)] * i % MOD;
            }
            if (k >= n) {
                System.out.println(0);
            } else if (k == 0) {
                System.out.println(factArr[(int) n]);
            } else {
                long res = 2 * nCr((int) n, (int) (n - k)) * computeSum((int) n, (int) k) % MOD;
                System.out.println(res);
            }
        }
    }
}
